SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END last_restock_cohort, MAX(last_restock) last_last_restock, ROUND(STDDEV(quantity), 2) stddev_quantity FROM inventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END HAVING stddev_quantity < 79 ORDER BY last_restock_cohort DESC;
